#!/usr/bin/env python3
"""Generate the submission PDFs and three twelve-page learning guides.

Run with Python plus reportlab. Source text lives here for review and maintenance.
Run scripts/quality.py first to include measured results. Does not invent approvals.
"""
from pathlib import Path
import csv
import json
import re
from xml.sax.saxutils import escape
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, KeepTogether, Image as FlowImage
from reportlab.graphics.shapes import Drawing, Rect, String, Line, Ellipse, Circle, Polygon
from reportlab.graphics import renderSVG

ROOT=Path(__file__).resolve().parents[1]; DOCS=ROOT/'docs'
S=getSampleStyleSheet()
S.add(ParagraphStyle(name='Body',fontName='Helvetica',fontSize=10.2,leading=14.2,spaceAfter=8))
S.add(ParagraphStyle(name='SmallBody',fontName='Helvetica',fontSize=8.2,leading=11.2,spaceAfter=5))
S.add(ParagraphStyle(name='GuideTitle',fontName='Helvetica-Bold',fontSize=21,leading=25,spaceAfter=16,textColor=colors.HexColor('#152b46')))
S.add(ParagraphStyle(name='GuideH',keepWithNext=True,fontName='Helvetica-Bold',fontSize=12.5,leading=17,spaceBefore=10,spaceAfter=7,textColor=colors.HexColor('#152b46')))
S.add(ParagraphStyle(name='CodeText',fontName='Courier',fontSize=8.7,leading=12,spaceAfter=8))
REQ=json.loads((DOCS/'requirements.json').read_text())
METRICS=json.loads((DOCS/'reports/summary.json').read_text()) if (DOCS/'reports/summary.json').exists() else None


def p(text,style='Body'):
    return Paragraph(escape(text).replace('\n','<br/>'),S[style])


def header(canvas,doc):
    canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#536579'))
    canvas.drawString(46, A4[1]-31, 'SMARTEXPENSE  |  TEAM 14  |  SOFTWARE ENGINEERING')
    canvas.drawString(46,28,'Sathik  -  Arya  -  Sahana')
    canvas.drawRightString(A4[0]-46,28,str(doc.page))


def pdf(name,story):
    SimpleDocTemplate(str(DOCS/name),pagesize=A4,rightMargin=46,leftMargin=46,topMargin=53,bottomMargin=47,
      title=Path(name).stem.replace('_',' '),author='Team 14').build(story,onFirstPage=header,onLaterPages=header)


def table(headers,rows,widths=None):
    data=[[p(str(x),'SmallBody') for x in row] for row in [headers]+rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#edf2f7')),('VALIGN',(0,0),(-1,-1),'TOP'),
     ('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),
     ('BOTTOMPADDING',(0,0),(-1,-1),5),('LINEBELOW',(0,0),(-1,0),0.5,colors.HexColor('#9caabd')),
     ('LINEBELOW',(0,1),(-1,-1),0.25,colors.HexColor('#dce3ea'))]))
    return t


def section(title,*paragraphs):
    return [p(title,'GuideH')]+[p(x) for x in paragraphs]


def title(subject,subtitle):
    return [p(subject,'GuideTitle'),p(subtitle),p('Version 2.1  |  November 2026  |  Current implementation and evidence')]


def arrow(d,x1,y1,x2,y2,label=None):
    d.add(Line(x1,y1,x2,y2,strokeColor=colors.HexColor('#304962'),strokeWidth=1))
    length=((x2-x1)**2+(y2-y1)**2)**0.5
    ux,uy=(x2-x1)/length,(y2-y1)/length
    d.add(Polygon([x2,y2,x2-6*ux-3*uy,y2-6*uy+3*ux,x2-6*ux+3*uy,y2-6*uy-3*ux],fillColor=colors.HexColor('#304962'),strokeColor=None))
    if label:d.add(String((x1+x2)/2,(y1+y2)/2+5,label,fontName='Helvetica',fontSize=8,textAnchor='middle'))


def usecase():
    d=Drawing(500,350)
    d.add(Rect(180,8,315,330,fillColor=colors.HexColor('#f8fafc'),strokeColor=colors.HexColor('#7890a7')))
    d.add(String(335,320,'SmartExpense system',textAnchor='middle',fontName='Helvetica-Bold',fontSize=11))
    for x,y,label in [(65,300,'Guest'),(65,170,'Registered user')]:
        d.add(Circle(x,y,9,fillColor=None));d.add(Line(x,y-9,x,y-36));d.add(Line(x-14,y-18,x+14,y-18));d.add(Line(x,y-36,x-12,y-50));d.add(Line(x,y-36,x+12,y-50));d.add(String(x,y-63,label,textAnchor='middle',fontSize=8))
    cases=[(335,285,'Register and login'),(335,235,'Logout'),(335,185,'Manage transactions'),(335,135,'Manage categories'),(335,85,'Set budgets and alerts'),(335,35,'Dashboard and export')]
    d.add(Line(80,280,230,285))
    for x,y,_ in cases:d.add(Line(80,148,x-105,y))
    for x,y,label in cases:
        d.add(Ellipse(x,y,105,19,fillColor=colors.white,strokeColor=colors.HexColor('#486987')))
        d.add(String(x,y-3,label,textAnchor='middle',fontSize=9))
    return d


def components():
    d=Drawing(500,220)
    for x,y,w,h,lines in [(0,145,130,65,['Browser UI','Jinja HTML and Canvas']), (180,120,155,100,['<<component>> Flask','Auth and sessions','Transactions and export','Budgets and dashboard']), (385,130,112,85,['<<component>> Data','SQLAlchemy ORM','SQLite tables']), (180,8,155,60,['<<component>> Validation','pytest and coverage','CI and security scans'])]:
        d.add(Rect(x,y,w,h,fillColor=colors.HexColor('#f2f6fa'),strokeColor=colors.HexColor('#486987')))
        for j,line in enumerate(lines):d.add(String(x+w/2,y+h-18-j*17,line,fontSize=9,textAnchor='middle'))
    arrow(d,130,175,180,175,'HTTP / JSON');arrow(d,335,175,385,175,'SQL')
    arrow(d,255,68,255,120,'verifies');return d


def sequence(kind):
    d=Drawing(500,250);names=['Browser','Flask route','Auth or validation','SQLite']
    xs=[45,170,320,455]
    for x,n in zip(xs,names):
        d.add(Rect(x-43,216,86,26,fillColor=colors.HexColor('#edf2f7'),strokeColor=colors.HexColor('#486987')))
        d.add(String(x,226,n,fontSize=9,textAnchor='middle'));d.add(Line(x,16,x,216,strokeColor=colors.HexColor('#a7b4c2'),strokeDashArray=[3,3]))
    steps=([(0,1,'POST login and CSRF'),(1,3,'Read user and guard'),(3,2,'Hash and lock check'),(2,3,'Save opaque session'),(1,0,'200 user and sid cookie')]
      if kind=='login' else [(0,1,'POST expense and CSRF'),(1,2,'Session and owner check'),(2,1,'Validate amount and date'),(1,3,'INSERT then COMMIT'),(1,0,'201 saved transaction'),(0,1,'GET dashboard'),(1,3,'Aggregate owner records'),(1,0,'200 totals and alerts')])
    for j,(a,b,label) in enumerate(steps):arrow(d,xs[a],198-j*23,xs[b],198-j*23,label)
    return d


DIAGRAMS={'use-cases':usecase(),'components':components(),'login-sequence':sequence('login'),'expense-sequence':sequence('expense')}


def build_srs():
    st=title('SmartExpense Requirements Specification','Requirements baseline for the three-member Team 14 application')
    st+=section('1 Introduction','SmartExpense lets a registered user record INR income and expenses, organize categories, set monthly and category budgets, inspect a dashboard and export a filtered CSV. The purpose is an explainable end-to-end Software Engineering mini project. Read requirements alongside the SAD, Test Plan and traceability.csv. Requirements retain their original SEB identifiers.',
      'This specification follows the supplied IEEE-style SRS structure; it is not a standards certification. Revised roster: Sathik, Arya and Sahana. Sathik maps to GitHub account gsathvik73-afk, Arya to arya7sai and Sahana to SahanaShivakumarBadiger. No instructor approval is implied by this revision.')
    st+=section('2 Overall description','The product is a self-contained layered web application: browser, Flask application and relational SQLite database. Guests may register and log in. Registered users access only their own data. Maintenance uses server commands; there is no administrator UI. A browser with JavaScript renders optional charts; numerical tables remain available.',
      'Constraints: three students, one semester, a single INR currency, free libraries and no bank integrations. Exclusions: bank or UPI credentials, automatic statement import, shared budgets, native apps, tax handling and external notifications. UPI is a text label for payment mode. Assumptions: users enter their own records; hosting and a domain are provided separately if deployed HTTPS is assessed.')
    st+=section('3 External interfaces','The UI contains registration/login, dashboard, transactions, edit and delete confirmation, categories and budgets. Every write requires a CSRF token. JSON requests use Content-Type application/json and an authenticated sid cookie; JSON reads use Accept application/json. Dates use YYYY-MM-DD and months YYYY-MM. Amounts are decimal strings in responses. See api-contract.md for route details.',
      'SQLite is accessed through SQLAlchemy. No hardware peripherals or financial APIs are used. HTTPS with TLS 1.2 or later is required on a public deployment. Local HTTP is a demo environment and does not close SEB-SR-001.')
    st.append(PageBreak());st+=section('4 Functional requirements','Every requirement below has one named owner for current delivery and review. Ownership is not historical code authorship. The linked case and measurable expected result form its acceptance criterion.')
    for r in REQ[:17]:
        st+=section(r['requirement']+' '+r['title'], 'The system shall '+{
         'SEB-F-001':'create a named account with a normalized unique email and valid password.',
         'SEB-F-002':'authenticate correct credentials and issue an eight-hour server-side session.',
         'SEB-F-003':'revoke the server-side session on logout and deny replay.',
         'SEB-F-004':'restrict all records, totals, categories and exports to the authenticated user.',
         'SEB-F-005':'save a positive expense with date, category, payment mode and optional note.',
         'SEB-F-006':'save income with positive amount, date and nonempty source.',
         'SEB-F-007':'reject nonpositive or invalid amounts, precision beyond two decimals and future transaction dates.',
         'SEB-F-008':'persist validated edits to an owned transaction and reflect them in totals.',
         'SEB-F-009':'require explicit confirmation before a browser form deletes an owned record.',
         'SEB-F-010':'filter owned records inclusively by date, category and amount, sort them and paginate at 50 records.',
         'SEB-F-011':'provide eight immutable default categories and allow private custom categories and renaming.',
         'SEB-F-012':'save one overall and optionally category-specific budget for each user and month.',
         'SEB-F-013':'compute spending, remaining amount and percentage from stored expenses to within INR 1.',
         'SEB-F-014':'warn at 80 percent through 100 percent and show a distinct alert above 100 percent without blocking entry.',
         'SEB-F-015':'show income, expense and net balance for a selected month, including zero states.',
         'SEB-F-016':'show category totals and a six-month spending trend including empty months.',
         'SEB-F-017':'export every matching owned transaction across all pages to a UTF-8 CSV with correct escaping.'}[r['requirement']],f"Priority {r['priority']}. Owner {r['owner']}. Acceptance: {r['expected']} Test {r['test_case']}.")
    st+=section('5 Non functional requirements')
    st.append(table(['ID','Measurable target','Verification'],[
      ['SEB-NF-001','At least 90 of 100 dashboard and list requests finish within 3 seconds with 5000 transactions.','TC-PERF-01; local request timings are not network-load acceptance.'],
      ['SEB-NF-002','20 independent concurrent sessions finish their actions without 5xx errors or mixed data.','TC-PERF-02'],
      ['SEB-NF-003','Committed records survive restart; a failed save leaves no partial write.','TC-REL-01'],
      ['SEB-NF-004','Five first-time users each add an expense within 3 clicks from Dashboard and correct an invalid amount.','TC-UX-01; real participants required.'],
      ['SEB-NF-005','Main flows work in current Chrome, Firefox and Edge and at 360px with no clipping.','TC-PORT-01; record versions and date.']], [80,275,148]))
    st+=section('5.1 Security','Objective SO1: preserve confidentiality of account and financial records through authenticated owner checks, private host storage and encrypted public transport. SQLite is not encrypted by this application. Objective SO2: preserve integrity by authorizing all changes, validating inputs and committing atomically.')
    st.append(table(['ID','Requirement and acceptance'],[
      ['SEB-SR-001','Public HTTP redirects to valid HTTPS using TLS 1.2 or later; Secure and HttpOnly cookies. TC-SEC-01.'],
      ['SEB-SR-002','Passwords are salted one-way bcrypt hashes; identical passwords have different hashes; no passwords in logs. TC-SEC-02.'],
      ['SEB-SR-003','All protected reads and mutations enforce session-derived ownership; foreign IDs return 403 or 404. TC-SEC-03.'],
      ['SEB-SR-004','ORM parameterization and escaped output keep SQL and script payloads inert; reject missing CSRF. TC-SEC-04.'],
      ['SEB-SR-005','Minimum password length 8 characters, maximum 72 UTF-8 bytes; five consecutive failures lock for five minutes. TC-SEC-05.']], [86,417]))
    st+=section('6 Quality attributes and acceptance','Money is positive, at most INR 9999999999.99 and has at most two decimal places. Income does not consume a budget. Remaining may be negative. Totals are computed on reads. Dates use server IST for the future-date check. Six-month dashboard queries require June 0001 or later to avoid calendar underflow.',
      'Exit criteria: all high-priority requirements pass, every requirement links to an executed case, no open Critical or Major defect, and manual/deployed evidence exists where required. The current build does not claim unconditional acceptance while five-real-user acceptance and valid public HTTPS remain open. The stable Chrome, Edge and Firefox desktop/360px matrix is verified in docs/reports/browser-acceptance.')
    st.append(PageBreak());st+=section('7 UML use case model','A guest can register or authenticate. A registered user manages owned records, categories, budgets and reports. Authentication is a precondition for all private use cases.');st.append(DIAGRAMS['use-cases'])
    st+=section('8 Requirements traceability matrix','The complete machine-readable RTM in traceability.csv links each of the 27 identifiers to source, test case, GitHub issue, owner, estimate and sprint. Requirements.json is the common data source. See the Test Plan case catalog for eight executable scenarios per functional requirement.')
    st.append(table(['Requirements','Design and code','Test family'],[
      ['F001-004; SR002-005','Auth and owner guards in routes.py; User, LoginSession and LoginGuard in models.py','AUTH and SEC'],
      ['F005-010','Transaction validation and owned CRUD; Transaction model','EXP'],['F011','Category management; Category model','CAT'],
      ['F012-014','Budget upsert and read-time calculations; Budget model','BUD'],['F015-017','Dashboard aggregations, Canvas tables and filtered export','DSH and RPT'],
      ['NF001-005; SR001','Performance, reliability, UX, browser and deployment boundaries','PERF REL UX PORT SEC']], [132,236,135]))
    pdf('SRS.pdf',st)


def build_sad():
    st=title('SmartExpense Architecture and Design','Actual Flask and SQLite implementation with traceable interfaces')
    st+=section('1 Introduction','This SAD explains the implemented structure and decisions for the three-member team. It updates earlier proposed designs and API examples. Readers should use SRS.pdf for required behavior, Test_Plan.pdf for verification and deviations.md for the change rationale. Revision 2.1 records November repairs and verified browser acceptance; approval remains with the team and evaluator.')
    st+=section('2 Document overview','Architecture describes responsibilities and trust boundaries. Design specifies data, request sequences, APIs and error behavior. The code has one Flask blueprint, an application factory, SQLAlchemy models, Jinja templates and local static assets. Logical modules are functions within routes.py; this is not a claim that separate service processes exist.')
    st+=section('3 Architecture','Choose a layered monolith: a small student project needs simple deployment and inspectable request flows. Browser HTML and Canvas form the presentation layer; Flask handles authentication, validation and business rules; SQLAlchemy and SQLite provide persistence. This keeps one transaction boundary per write and avoids distributed-service overhead. SQLite suits the measured local load but has one writer at a time. A larger deployment would need measured capacity work and a reviewed database migration.')
    st.append(DIAGRAMS['components'])
    st+=section('3.1 Components and interfaces','The application factory configures CSRF, cookies, headers and error handling. The blueprint loads the opaque sid token, resolves its unexpired server-side session and exposes g.user. Protected routes redirect anonymous browsers or return JSON 401. All record queries derive user_id from g.user. Shared defaults have a NULL owner; private categories must match g.user.id.',
      'Auth functions use bcrypt and LoginGuard. Transaction functions validate amount, date, category and type-specific fields, then commit owned CRUD. Budget functions upsert unique scope records. Dashboard functions aggregate current records without storing duplicate totals. Export reuses transaction_rows with limit=None and neutralizes dangerous spreadsheet prefixes.')
    st+=section('3.2 Technology and security architecture','Python 3.11, Flask, Flask-SQLAlchemy, Flask-WTF, bcrypt, SQLite, Jinja and a local Canvas chart script. Exact dependency pins are in requirements-lock.txt. The development lock adds coverage.py, pyflakes and Bandit. Actions runs tests and builds a non-root Gunicorn container. Public HTTPS requires an external reverse proxy; no untrusted forwarded headers are assumed.',
      'Threat model: spoofing is reduced by bcrypt, unpredictable sessions and expiry; tampering by CSRF, validation and owner checks; disclosure by no-store responses, escaped output, CSP and safe logs; brute-force attempts by five-failure lockout. Account lockout may itself be abused for denial of service. Unknown-user timing is not made constant. No exhaustive penetration test or encrypted SQLite storage is claimed.')
    st.append(PageBreak());st+=section('3.3 Architectural decisions and traceability','ADR1: layered monolith for reviewability and small-team maintenance. ADR2: decimal arithmetic for business calculations; SQLite Numeric storage is not an arbitrary-precision accounting ledger. ADR3: server-side sessions permit logout revocation. ADR4: eight shared immutable categories plus private custom categories. ADR5: read-time aggregation avoids stale totals. ADR6: Actions replaces the generic Jenkins example because Part 2 explicitly requests Actions.')
    st.append(table(['Requirement family','Component and code','Evidence'],[
      ['F001-004; SR002-005','Auth, session and owner functions; models.py','test_core.py; test_security.py'],['F005-010','validate_transaction, owned_transaction and CRUD','test_transactions.py; test_regressions.py'],
      ['F011-014','categories, visible_category, budget_list, expense_sum','test_core.py; requirement scenarios'],['F015-017','dashboard_data, transaction_rows, transaction_export','core, CSV and scenario suites'],
      ['NF001-003','Indexed queries and transaction rollback','test_nonfunctional.py'],['NF004-005; SR001','UI, hosting and browser boundary','Browser report plus pending external checks']], [124,230,149]))
    st+=section('4 Design','Data model: User has unique normalized email and password_hash. LoginSession has a random token primary key, user_id and expiry. LoginGuard has one row per user, failure count and optional locked_until. Category has nullable user_id and a name. Transaction has owner, expense/income type, Numeric amount, date, optional category, payment mode, source and note. Budget has owner, YYYY-MM month, optional category and positive limit.',
      'Database checks reject invalid transaction types, nonpositive amounts and missing type-dependent fields. Composite indexes cover transaction owner/date and owner/category. A unique expression index on owner, month and coalesce(category_id,0) ensures a single overall budget even with NULL scope. Application checks prevent referencing another user category. init-db creates missing tables and defaults without deleting existing data; it does not migrate existing columns.')
    st+=section('4.1 Business calculations','Expense total sums only owned expense records in the selected month. Balance equals income minus expense. Budget spent is overall expense or the category-specific sum. Remaining equals limit minus spent; percentage is spent times 100 divided by the positive limit. Warning begins at exactly 80 percent and includes 100 percent; over-budget means strictly greater than 100 percent. Six trend buckets cover the selected month and its five predecessors, including year rollover and zero months.')
    st.append(PageBreak());st+=section('4.2 UML sequence diagrams','Login success checks CSRF, reads user and guard, verifies bcrypt, resets failure state, stores an opaque session and returns the cookie. Wrong credentials return 401. During lockout the response is 429 with Retry-After. No password is included in logs.');st.append(DIAGRAMS['login-sequence'])
    st+=section('Expense creation and subsequent dashboard read','The write response contains the saved transaction. The browser redirects to Transactions; the dashboard recomputes totals on a later read. This replaces the earlier design promise that every creation response includes budgets and alerts. Failure before commit rolls back and returns a safe retry message.');st.append(DIAGRAMS['expense-sequence'])
    st+=section('4.3 API design','Authentication interface: GET /login provides a CSRF token. POST /register accepts name, email and password and returns 201 with user id/name. POST /login accepts email/password and returns 200 with user id/name plus sid. POST /logout returns {ok:true} and revokes the server session. Browser posts redirect instead of returning JSON.',
      'Transaction interface: GET /transactions lists up to 50 owned matches plus page, has_next and the total across matches. POST creates and returns 201 {transaction:{...}}. GET /transactions/{id} returns one owned record. PUT updates valid fields; DELETE removes an owned record. Form edit and confirmation routes support browsers. GET /transactions/export.csv returns all filtered rows with date,type,category,amount,payment_mode,source,note headers.',
      'Budget interface: GET /budgets reads a month. PUT or POST accepts month, limit and nullable category_id, then upserts one scope and returns the saved budget. GET /api/dashboard?month=2026-10 returns month, income, expense, balance, budgets, categories and trend. See api-contract.md for exact request and response examples.')
    st+=section('4.4 Error handling and logging','Validation returns 422 with field messages. Anonymous JSON requests get 401; foreign/absent records get 404; editing defaults gets 403. CSRF failures return 400. JSON HTTP errors use stable error identifiers. Unexpected failures roll back and return 500 with a retry message and a request reference. Failure logs contain endpoint, request reference and exception type, not SQL parameters or entered financial data. A 64 KiB request limit returns 413 for oversized requests.')
    st+=section('4.5 UX and open issues','Labels, short forms, retained invalid values, a Dashboard Add Expense link, explicit delete confirmation, text threshold messages and responsive table wrappers support the intended flow. Canvas charts have numerical table counterparts. The stable Chrome, Edge and Firefox desktop/360px matrix passed 90 checkpoints and closes issue 26. Five first-time users and valid deployed HTTPS remain open as issues 25 and 27; see evaluation-checklist.md.')
    st+=section('5 References and terms','Project SRS version 2.0; Test Plan version 2.0; supplied SAD template and Deliverables Parts 1-3; source code in smartexpense. UML describes structural and interaction models; API means application programming interface; ORM means object-relational mapper; CSRF means cross-site request forgery. Architecture is explained using the supplied IEEE-style outline without claiming formal certification.')
    pdf('SAD.pdf',st)

def build_test_plan():
    st=title('SmartExpense Test Plan','SEB TP 002 with execution evidence and functional scenario catalog')
    st+=section('1 Introduction','This plan uses the supplied IEEE-style outline to verify the current three-member application. It covers isolated unit rules, database-backed route integration, full functional scenarios, security, concurrency, durability and browser smoke tests. The goal is evidence of correct behavior with explicit limits, rather than a passing-test count alone. References: SRS.pdf, SAD.pdf, requirements.json and the teacher deliverables in source-reference.')
    st+=section('2 Test items','Application factory and security headers; registration, login, logout and server-side sessions; transactions, categories, budgets, dashboard and filtered export; SQLAlchemy models and SQLite constraints; browser forms, responsive layout and local chart script; deployment configuration and HTTPS acceptance.')
    st+=section('3 Features to be tested','All seventeen functional, five nonfunctional and five security requirements retain their identifiers. Each functional requirement has eight separately executed integration scenarios in test_requirement_scenarios.py, giving 136 catalog entries. Unit tests independently check money and month boundaries. Existing suites test security, transaction behavior, CSV, rollback, performance and concurrency. Browser recordings use real HTML form submissions and synthetic accounts.')
    st+=section('4 Features not to be tested','Bank/UPI integration, tax calculations, statement imports, native mobile applications and shared budgets are outside scope. No real bank data or personal financial database is used. This plan does not infer five-user usability acceptance from one automated browser, nor public TLS from a local Secure-cookie configuration.')
    st+=section('5 Test approach','Unit: isolated money conversion, formatting, leap-year and month validation. Integration: each HTTP route interacts with a temporary SQLite database. System: account-to-dashboard flows, expense/income CRUD, category selection, budgets and export. White-box branch measurement records executed exits; black-box assertions check status, fields, totals and ownership.',
      'Entry criteria: dependencies installed from pins, stable application factory, separate temporary database and known sample data. Baseline A: income INR 10000; Food expense 500, Travel 300 and Rent 1000; expense 1800 and balance 8200. Budget baseline: monthly 5000 and Food 1000. Tests reset state per case. Test-only hashing cost is reduced only inside the 136 scenario suite; original security and concurrency tests use the production bcrypt cost.')
    st+=section('5.1 Security validation','Use two synthetic users. Test password boundaries, different bcrypt salts, login lockout and expiry, logout cookie replay, cross-user reads/edits/deletes, SQL-injection and stored-XSS payloads, missing CSRF, no-store/CSP headers, formula-safe CSV and safe errors. Malformed category IDs and oversized amount filters must not bypass checks or trigger 500. Scan application source with pyflakes and Bandit without blanket security exclusions.',
      'For a public target, run TC-SEC-01 with SEB_DEPLOYED_URL: check HTTP redirect, valid certificate, TLS protocol and Secure/HttpOnly cookies. Without that target the two deployment tests skip and the requirement remains open. Authorized testing is limited to this application and synthetic data.')
    st+=section('6 Environment','Python 3.11 with exact pins, pytest, coverage.py branch mode, pyflakes and Bandit. Temporary SQLite files isolate tests. Browser acceptance separately runs stable Chrome, Edge and Firefox at 1280px and 360px; its report records actual versions, screenshots and viewport. Earlier retrospective recording uses isolated Chromium. CI uses Ubuntu. Local test-client timings do not measure a public network or production service. Docker build and deployable package are checked by CI.')
    st+=section('7 Schedule','Teacher baseline: Sprint 1 October 19-23, Sprint 2 October 26-30, testing November 2-6. Current recovery begins November 15. These historical dates are not rewritten as achieved dates. Execute unit tests, full regression with coverage, scans, browser smoke, report review and freeze review in dependency order. A failure suspends the affected acceptance and triggers a targeted fix and rerun.')
    st+=section('8 Deliverables','Four named reports live in docs/reports: unit-test-report.md and XML, system-validation-report.md and XML, code-coverage-report.md, and branch-coverage-report.md. Also retain coverage JSON/XML/HTML, test logs, security/static scans, browser screenshots and catalog CSV. Videos are in docs/videos. Scripts/quality.py regenerates the reports; CI uploads fresh artifacts for its exact revision.')
    st+=section('9 Responsibilities','Sathik verifies accounts, sessions, budgets, dashboard and release integration. Sahana verifies end-to-end transaction creation, validation, edits, deletion and filters. Arya verifies complete filtered CSV reporting, quality evidence and security acceptance. Every person reads the whole architecture and reviews changes outside their primary area. GitHub issues assign current responsibility; Git history determines authorship.')
    st+=section('10 Risks and mitigation','SQLite contention: keep costly bcrypt verification outside held write locks and rerun the concurrent-user check. False passing results: assert persisted values and totals in addition to status codes. Mutable dates: use fixed past transaction fixtures plus an explicit future-date case. Secret exposure: separate temporary databases, ignored instance directories and synthetic accounts. Coverage inflation: no source exclusions or blanket nosec suppressions; report actual misses.')
    st+=section('11 Assumptions and dependencies','Manual tests need participants and the actual requested browser versions. Public TLS needs hosting and a valid domain. GitHub Projects needs project-scoped access. These constraints stay visible in evaluation-checklist.md. Passing automation cannot substitute for genuine member-authored PRs or instructor approvals.')
    st+=section('12 Suspension and resumption','Suspend affected tests on server startup failure, data corruption, authentication failure or a Critical disclosure. Restore a clean synthetic database, correct the defect and run smoke plus related regression tests before resuming. On a failed save verify rollback and successful retry; do not simply hide exceptions.')
    st+=section('13 Test management and traceability','Each case has a unique ID, requirement, module, description, preconditions, steps, test data, expected result, actual result and outcome in test-cases.csv. IT-F001-01 through IT-F017-08 are actual automated executions. Manual execution is a separate column and is not marked passed without a human run. Original TC family IDs remain in requirements.json. JUnit properties connect executable scenarios to catalog IDs.')
    st+=section('14 Metrics and reporting','Pass/fail/skip totals come from JUnit XML. Statement coverage equals covered executable lines divided by total statements. Branch coverage equals covered branch exits divided by possible branch exits. Combined coverage combines statements and exits and must not be mislabeled as either individual metric. No requirement acceptance is inferred only from these percentages. Record build revision and dirty-tree flag with execution time.')
    st+=section('15 Approvals and exit criteria','No team or instructor sign-off is fabricated. Acceptance requires all high-priority requirements passed, every requirement mapped, no Critical/Major defects, and all applicable manual/deployed evidence. Code freeze may identify a candidate while external checks remain open; it is not unconditional acceptance.')
    st.append(PageBreak());st+=section('16 Functional case catalog','The CSV contains the full required columns. Each row below names one requirement and its eight independently executed scenarios. The source test assertions define each precise observation; the adjacent JUnit XML records the actual result.')
    import ast
    tree=ast.parse((ROOT/'tests/test_requirement_scenarios.py').read_text())
    scenarios=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='SCENARIOS' for t in n.targets))
    for n,cases in scenarios.items():
        r=REQ[n-1];st+=section(r['requirement']+' '+r['title'], ' | '.join(f'{i+1:02} {case}' for i,case in enumerate(cases)),f"Baseline and procedure: run IT-F{n:03}-01 through IT-F{n:03}-08 with an isolated database. Acceptance family: {r['test_case']}. Expected: {r['expected']}")
    st+=section('17 Non functional and security cases','TC-PERF-01 seeds 5000 rows and measures 100 requests for each page; at least 90 must finish in 3 seconds. TC-PERF-02 runs 20 independent users with 260 total actions and reconciles owned saves. TC-REL-01 restarts the app on the same database and forces commit failure after flush. TC-UX-01 needs five first-time users; TC-PORT-01 needs the requested current browser matrix. TC-SEC-01 needs a deployed URL. TC-SEC-02 to 05 cover hashing, ownership, injection/XSS/CSRF and lockout.')
    pdf('Test_Plan.pdf',st)


def build_plan():
    st=title('SmartExpense Project Plan','Team 14 scope ownership estimates schedule and recovery plan')
    st+=section('1 Lifecycle and scope','Use Agile with two planned increments and a testing phase because the team can deliver a working vertical slice, receive feedback and correct acceptance gaps. A user story connects a need to measurable acceptance; a sprint chooses a feasible set from the product backlog. The original schedule is a baseline, not a record fabricated after completion. Current changes are reconciliation work beginning November 15.')
    st+=section('2 Team and product ownership','Sathik: account lifecycle plus budgets and dashboard. Arya: complete filtered CSV reporting plus quality/security verification. Sahana: transaction lifecycle with validation, edits, deletion and filtering. These are vertical functional responsibilities spanning UI, server, storage and tests. Testing or database work alone is not a full feature. Current assignment does not change who originally authored a commit.')
    st+=section('3 Tools and reuse decisions','Git and GitHub provide history, issues, milestones and PRs. GitHub Actions tests and builds a container. pytest and coverage.py provide executable evidence; pyflakes and Bandit perform source checks. ReportLab produces PDF documents. Reuse Flask, SQLAlchemy, Flask-WTF, bcrypt and SQLite because they provide reviewed web, persistence, CSRF and hashing primitives. Build the expense rules, owner-scoped queries, dashboard, CSV handling, tests and documentation as project-specific code.')
    rows=[['Requirements and traceability','All three','12','0.075'],['Accounts and sessions','Sathik','14','0.088'],['Budgets and dashboard','Sathik','18','0.113'],['Transaction lifecycle','Sahana','24','0.150'],['Categories and entry usability','Sahana','10','0.063'],['CSV and reporting verification','Arya','12','0.075'],['Security and quality evidence','Arya','20','0.125'],['Integration and documentation','All three','18','0.113'],['Demo rehearsal and review','All three','12','0.075']]
    st+=section('4 Work breakdown and rough effort','These are rough planning estimates, not timesheets. One person-month is defined here as 160 hours. Total planned effort is 140 person-hours, or 0.875 person-month. Story points measure relative complexity and risk; they are not converted automatically into hours.')
    st.append(table(['Work package','Responsible','Person hours','Person months'],rows,[215,95,85,108]))
    st+=section('5 Schedule and Gantt view','Teacher schedule: backlog by October 12; dry run October 12-16; Sprint 1 October 19-23; Sprint 2 October 26-30; testing November 2-6. A potential third sprint was allowed for spillover in the testing week. November repairs are labelled recovery and do not claim to have met these dates.')
    st.append(table(['Work','Oct 12 to 16','Oct 19 to 23','Oct 26 to 30','Nov 2 to 6','Nov 15 onward'],[
      ['Backlog and design','Plan','','','','Reconcile'],['Account and budget slice','','Build','','','Review'],['Transactions and reports','','','Build','','Repair'],['Testing and coverage','','Smoke','Regression','Validate','Rerun'],['Documents and videos','','Increment 1','Increment 2','Finalize','Reconcile and record']], [124,76,76,76,76,75]))
    st+=section('6 Backlog and sprint allocation','All 27 requirements have an individual assignee, a story-point estimate, an acceptance case and a planned sprint in requirements.json and the GitHub issues. Sprint 1 represents foundation: accounts, categories, budgets and dashboard. Sprint 2 represents transaction integration, reporting and quality/security acceptance. The GitHub Project setup script creates numeric Story Points and a Sprint field when Projects permission is available. Labels and milestones provide a usable backlog in the meantime.')
    st+=section('7 Definition of done and review','A story is accepted only when its behavior meets the SRS, relevant unit/integration/security checks pass, documentation and traceability are updated, CI is green and a genuine reviewer has assessed the PR. The assigned member opens their own PR. Reviewers examine the diff and acceptance evidence; avoid empty commits, authorship substitution, backdating or self-approval presented as independent review.')
    st+=section('8 Risks dependencies and freeze','Highest risks are stale documentation, missing human evidence, permission gaps, SQLite write contention and unverified hosting. Track each gap explicitly. Preserve working data during startup; never commit local instance files. Record an actual release candidate revision after CI succeeds. Freeze that candidate while permitting separately reviewed fixes; do not declare all acceptance done when external requirements remain open.')
    st+=section('9 Communication and maintenance','Use GitHub issues and PRs for project work; no Jira is required for this handoff. Each guide provides a short rehearsal and a code-reading path. The maintenance plan covers backups, rollback, dependency changes, logging and defect severity. No estimates, assignments or signatures are represented as measured human work without supporting evidence.')
    pdf('Team14_Project_Plan.pdf',st)

COMMON_GUIDE = {
2: ('Web requests and Python foundations',[
('What the browser and server do','A browser sends a method, URL, headers, cookies and sometimes a body. GET reads a resource; POST creates or performs an action; PUT updates; DELETE removes. The Flask server matches the URL to a decorated function. Jinja renders HTML for browser screens; jsonify produces JSON for scripts and tests. An HTTP 200 means a request succeeded, 201 means a record was created, 302 redirects, 401 means authentication is missing, 403 means forbidden, 404 means unavailable, 422 means validation failed and 500 means an unexpected server failure.'),
('Read the Python you submit','A dictionary stores named values such as amount or date. A list stores rows. A function packages reusable behavior. A decorator wraps another function: @protected checks authentication before allowing the route to run. try/except converts a known invalid input into a useful result; it should not silently erase unexpected defects. with app.app_context() makes Flask configuration and the database session available to scripts and tests. Imports connect modules; a package contains __init__.py.'),
('Trace one expense request','The form includes csrf_token. The browser sends POST /transactions with its cookies. CSRFProtect checks the request. load_user resolves sid into an unexpired LoginSession and g.user. @protected denies an anonymous request. payload reads a form or JSON object. validate_transaction checks type, amount, date and category ownership. The route creates a Transaction using g.user.id, commits, and returns JSON 201 or redirects. A later GET rebuilds the list and dashboard from stored data.'),
('Sessions and request state','g belongs to the current request; it is not shared persistent storage. A cookie is held by the browser. The sid cookie contains an unpredictable token; its database row identifies the user and expiry. The separate signed Flask session supports CSRF. A JSON write still needs CSRF because authentication is cookie based. Never trust a user_id submitted by the browser.'),
('Rehearse','Open routes.py and locate the decorators, input parsing, validation, database write and response for one route. Explain what happens if validation fails and why that branch must not commit. Then locate the corresponding test rather than guessing from the UI.')]),
3: ('Database and money foundations',[
('Entities and relationships','User represents an account. LoginSession belongs to a user and expires after eight hours. LoginGuard tracks failures and a temporary lock. Category is either a shared default with NULL user_id or a private user category. Transaction belongs to a user and can refer to a visible category. Budget belongs to a user and may refer to a category; NULL category means the overall monthly budget. IDs are primary keys, and foreign keys describe relationships.'),
('Read the constraints','User.email is unique after normalization. Transactions require positive amounts and one of expense or income. Expense requires category and payment mode; income requires source. The application rejects foreign category IDs even if the row exists. Budgets require a positive limit. Their unique index includes coalesce(category_id,0), so NULL overall scope cannot produce duplicate budgets for the same user and month. A declared foreign key is not a substitute for request authorization.'),
('Why Decimal matters','Binary floating point cannot exactly represent many decimal fractions. money converts input to Decimal, rejects non-finite values, nonpositive values, more than two decimals and amounts beyond 9999999999.99. fmt emits two decimal places. SQLAlchemy Numeric and Python Decimal support these business calculations, but SQLite is not an arbitrary-precision financial ledger. Do not claim this mini project is a banking-grade accounting system. A future ledger could store integer paise with carefully tested migrations.'),
('Transactions and indexes','db.session.add stages a row; flush sends changes within the transaction; commit makes them durable; rollback discards uncommitted changes. The rollback test forces failure after flush and verifies that no half-save remains. Owner/date and owner/category indexes help queries narrow records, but an index is not a permission check. Every relevant query still needs user_id == g.user.id.'),
('Calculate aloud','Baseline income is 10000. Food 500 plus Travel 300 plus Rent 1000 gives expense 1800 and balance 8200. With monthly limit 5000, remaining is 3200 and usage is 36 percent. Food limit 1000 gives 50 percent. An expense of 250 changes expense to 2050 and balance to 7950. Income never consumes a budget. Reset the baseline between independent viva examples.')]),
6: ('Security controls and their limits',[
('Authentication versus authorization','Authentication proves which account is using the app; authorization decides whether that account may access a record. bcrypt verifies a password against a salted one-way hash. Two identical passwords should produce different hashes. Owner-scoped queries then restrict transactions, budgets, custom categories, dashboard sums and CSV. Returning 404 for a foreign record avoids confirming whether it exists.'),
('Sessions and login failure control','Login generates an unpredictable server-side token with an eight-hour lifetime. Logout deletes the row, so replaying the old cookie fails. The cookie uses HttpOnly and SameSite=Lax; Secure is enabled for HTTPS hosting. LoginGuard persists failure counts across restarts. Five failures start a five-minute lock; attempts while locked return 429 with Retry-After. Expiry permits a new attempt, and successful login resets the guard. Explain the distinction between a password hash and a random session token.'),
('CSRF SQL injection and XSS','CSRF checks ensure that a cookie-authenticated write originated from a page holding the token. They do not replace ownership checks. SQLAlchemy constructs parameterized queries instead of concatenating user text into SQL. Jinja escapes user text, and the chart script uses local data. The Content Security Policy restricts scripts to local resources and rejects framing. Store script-like notes as inert text; never add a safe filter merely to make user HTML render.'),
('CSV and errors','Spreadsheet programs may interpret a cell beginning with =, +, - or @ as a formula. Export prefixes dangerous text with an apostrophe and uses csv.writer for commas, quotes and line breaks. Unexpected write failures roll back and return a retry message with a request reference. Logs omit SQL parameters, financial notes, passwords and tokens. A validation response names the field and correction without revealing internal stack traces.'),
('Do not overclaim','The app does not encrypt the SQLite file or establish HTTPS by setting a header. A real public host needs TLS 1.2 or later, a valid certificate, HTTP redirect and Secure cookies. Backups need private filesystem permissions and host disk protection. Lockout can be abused for denial of service, and unknown-user timing is not made constant. A passing static scan is not a complete penetration test.')]),
7: ('Tests coverage and evidence',[
('Different levels answer different questions','Unit tests isolate rules such as money conversion or month bounds. Integration tests exercise Flask routes with a real temporary SQLite database. System checks follow account-to-report behavior through the application. Security tests use hostile input and a second user. Performance checks seed 5000 rows and measure 100 loads per page; concurrency uses 20 independent users. These dimensions overlap, so do not add their counts as if every category were disjoint.'),
('Read an assertion','A test creates known inputs, performs an action and asserts an observable result. A response status alone is weak evidence: tests also inspect persisted rows, totals, owner separation and CSV content. Fixtures create a fresh database so earlier cases do not contaminate later ones. The scenario suite has eight independent cases for each functional requirement, 136 in total. Its test-only bcrypt cost is reduced for speed; the existing security and concurrency suites retain production cost.'),
('Interpret the reports','scripts/quality.py produces unit JUnit XML, a complete-suite system report, coverage JSON/XML/HTML and source/security scans. The system report includes the whole regression suite, including unit cases; its total is not an additional independent set. Statement coverage measures executed executable lines. Branch coverage measures executed branch exits. The combined percentage weights both; quoting it as pure branch coverage is incorrect. Read the missing-line and missing-branch details before claiming thoroughness.'),
('What skipped tests mean','The two deployed HTTPS checks skip when SEB_DEPLOYED_URL is absent. Skipped means not executed, not passed. The separate stable Chrome, Edge and Firefox matrix passed 90 checkpoints at desktop and 360px and is recorded under docs/reports/browser-acceptance. Five-first-time-user acceptance still needs actual participants. Local Flask-client response timings exclude network latency and public-host load.'),
('Practice the command','Create an isolated environment, install requirements-dev.txt and run python scripts/quality.py. Inspect unit-test-report.md, system-validation-report.md, code-coverage-report.md and branch-coverage-report.md. Find one failing assertion or uncovered exit and explain how an input would reach it. CI artifacts are authoritative for the exact pushed revision; locally committed reports also record their base revision and dirty-tree flag.')]),
8: ('Requirements design and SDLC traceability',[
('Know the document chain','The SRS says what must happen and how to verify it. The SAD says how components, data and interfaces deliver that behavior. The Test Plan defines the approach, fixtures, cases, exit conditions and evidence. The RTM connects requirement to design, source and case. A GitHub issue connects that requirement to an owner, estimate, sprint and PR. A test report then records what actually executed. Show this chain for a single requirement during the viva.'),
('Read the UML','A use-case diagram shows actors and goals inside the system boundary; it is not a database diagram. The component diagram shows browser, Flask responsibilities and persistence. Sequence diagrams show ordered messages over time: login and expense creation followed by dashboard read. They should match the actual API responses. A class or entity view explains fields and relationships. Be able to redraw the important relationships without reciting notation mechanically.'),
('Explain permitted design changes','The current login JSON returns user id and name, not the old message example. Expense creation returns the saved transaction, while a later dashboard GET computes totals. LoginGuard is separate from User so init-db can add lockout storage without replacing accounts. CSV covers all filtered pages rather than only the visible 50 rows. Local Canvas charts and numerical tables replace the proposed external chart library. deviations.md records these differences and their reasons.'),
('Use measurable requirements','A statement such as fast is not testable without a threshold and context. SEB-NF-001 specifies 90 out of 100 loads within three seconds with 5000 transactions. SEB-F-014 specifies the exact 80 and 100 percent boundaries. Security objectives express desired confidentiality and integrity; security requirements specify observable controls such as owner checks and lockout. Priority is not the same as a pass result.'),
('Exercise','Choose one requirement outside your primary area. Show its SRS paragraph, SAD component, source function, test name and GitHub issue. State whether evidence is automated, browser-based, manual or deployed. Explain the remaining acceptance condition if the requirement is open. This is stronger viva preparation than memorizing a feature list.')]),
9: ('Agile planning estimation and teamwork',[
('Explain the lifecycle','The project uses Agile increments because a working slice can be demonstrated, tested and refined. Requirements and design still matter; Agile does not mean starting without a plan. The product backlog includes all known work. A sprint backlog is the selected work for one increment. Definition of done includes working behavior, tests, security review, documentation and evidence. A retrospective examines what impeded delivery and how the process changes.'),
('Original schedule and current recovery','The teacher baseline planned backlog by October 12, Sprint 1 October 19-23, Sprint 2 October 26-30 and testing November 2-6. The current repair is recorded in November. Retrospective videos demonstrate the repaired build and are labelled accordingly. Do not say these new files were created during October or that all original milestones were met. Explain what evidence existed then and what was repaired now.'),
('Estimates and ownership','Story points estimate relative complexity, uncertainty and risk. They are not hours, marks or commit counts. Requirements.json contains points, owner and sprint for all 27 requirements. The work breakdown estimates 140 person-hours, using 160 hours per person-month, or 0.875 person-month total. These are planning assumptions, not measured time sheets. A full functionality spans user input, business rules, persistence and validation; UI-only or testing-only activity is not automatically a vertical feature.'),
('Each person understands integration','Sathik owns accounts, budgets and dashboard responsibility. Sahana owns transaction lifecycle responsibility. Arya owns reporting/export and quality/security responsibility. Everyone should explain the complete request path and one dependency on another area. Current responsibility does not retroactively author someone else\'s code. Original PRs and commits establish actual work. New AI-assisted repairs remain attributed to the account that performed them.'),
('Blockages and closure','Describe concrete blockers such as missing project scope, unavailable public hosting or incomplete participant testing. An issue is not done just because code exists; close it when its acceptance evidence exists. Explain the earlier SQLite contention defect: costly bcrypt checks must not unnecessarily hold a database write lock. A productive retrospective links the observed defect to the fix and its regression test.')]),
10: ('Git branches PRs reviews and honest evidence',[
('The minimum mental model','Git stores snapshots as commits. A branch names a line of development; a remote points to another repository. Fetch updates remote-tracking references without replacing local work. Pull fetches and integrates changes. Push publishes local commits. A PR asks to review and integrate a branch; it is a GitHub object rather than a Git commit. A merge commit can preserve the relationship between two lines of development.'),
('Use a focused workflow','Start from updated main and create a clearly named branch. Implement a meaningful change with its requirement and tests. Inspect git diff and git status, stage only intended files and commit a descriptive message. Push the branch and open a PR from your own account. Link the GitHub issue, explain the behavior and validation, request a real review and wait for CI. Resolve review findings, then merge the reviewed revision. Never commit .env files, instance databases or local secrets.'),
('Useful commands','git status\ngit diff\ngit switch -c feature/your-scope\ngit add path/to/changed-file\ngit commit -m "Explain the behavior changed"\ngit push -u origin HEAD\ngit log --graph --oneline --decorate --all'),
('What a reviewer checks','Review input validation, owner constraints, transaction boundaries, side effects, API compatibility and test quality. Read the exact diff rather than approving from a passing badge. Reproduce the main acceptance case and inspect failures. A reviewer should not approve their own PR or present an automated check as an independent human review. Explain who opened the PR, who reviewed it and which commit CI tested.'),
('Evidence should match reality','Do not fabricate dates, fake author emails, split empty commits for numerical quotas or impersonate a teammate. Assignment is not authorship. AI use is permitted, but each member must explain and verify the result. The original Arya PR 3 and Sahana PR 4 remain available. The current recovery adds actual focused commits on their actual dates. If asked for individual evidence, show your real PR and the code you understand.')]),
11: ('Demonstration operations and recovery',[
('Run a clean demo','Use ./run.sh, open http://127.0.0.1:5050, register a synthetic account and log in. The launcher creates the environment, installs pins, prepares tables and stores a private key under ignored instance. Rerunning should preserve existing data. Choose PORT=5051 if the default is occupied. Never show personal notes, passwords, tokens or real financial records to the evaluator.'),
('A coherent demonstration','Start with one requirement and a known dataset. Add income 10000 and expenses Food 500, Travel 300 and Rent 1000 in the chosen month. Show balance 8200. Set monthly budget 5000 and Food budget 1000; explain 36 and 50 percent. Add, edit and cancel a delete, then confirm another deletion. Filter and export, comparing all matching rows. Show threshold boundaries with suitable limits and explain that alerts never block entry.'),
('Fifteen minute presentation plan','Use two minutes for problem, scope and SRS; three for architecture, data and sequence diagrams; four for the working use cases; two for backlog, PR and review evidence; two for test results and coverage; two for deviations, maintenance and questions. Each member should speak about their feature and one integration point. The one- and two-minute videos are shorter supporting artifacts, not the full final presentation.'),
('Recover without hiding a problem','If login fails, check account state and the five-minute lock rather than editing production data live. If the port is busy, restart on an available local port. If a save fails, show the safe retry message and request reference, then inspect sanitized logs. If a database change is needed, back up safely before modifying it. init-db creates missing tables but is not a general migration engine.'),
('Deployment and maintenance','A Docker image and Gunicorn package are prepared in CI. Public hosting needs persistent storage, a strong secret and an HTTPS reverse proxy; Secure cookies only work over HTTPS. Back up SQLite through its online backup API or stop writes before copying. Test a restore in a separate instance, run integrity checks and smoke tests, and keep a known release tag for rollback. State remaining acceptance gaps plainly rather than improvising a success claim.')])
}

ROLE_GUIDE={
'Sathik':{
1:('Your learning path and project responsibility',[
('What you should be able to explain','You should be able to start SmartExpense, show an account-to-dashboard journey, trace the corresponding Python functions and defend the acceptance evidence. Your primary functional responsibility is accounts, sessions, budgets and dashboard integration. Your GitHub account is gsathvik73-afk. The older Git history uses the account holder\'s full name; the current project materials use Sathik as requested. A document assignment does not change historical authorship.'),
('Start from the problem','The product helps a student understand manually entered income and spending in INR. It records transactions, groups expenses, stores monthly limits and shows spending patterns. It is not connected to a bank. A useful opening statement is: our system keeps each user\'s records separate and computes their monthly balance and budget usage from saved transactions. Explain the benefit before naming Flask or SQLite.'),
('Study order','First run the app with synthetic data. Read models.py and sketch User, LoginSession, LoginGuard, Category, Transaction and Budget. Then read create_app, load_user, protected, register, login, logout, expense_sum, dashboard_data and budget_list. Run the auth, budget, dashboard and security tests. Finally inspect one real PR and the quality reports. Pages 4 and 5 provide the detailed path for your area; the other pages prepare you for the shared viva.'),
('Evidence you should bring','Show the original account/budget foundation PRs and the actual integration and recovery PRs from your account. Explain which work was AI-assisted and how it was checked. Show a requirement flowing from SRS to code to test report. Do not describe a review you have not performed or a teammate change as your authorship. Use the actual remote PR page for identities and dates.'),
('Completion exercise','Without looking at this guide, calculate the baseline totals, explain logout replay rejection, show exactly when an 80 percent warning appears and identify the three remaining external acceptance items. If you cannot explain a line that will be presented, trace it in a debugger or a focused test before the viva.')]),
4:('Accounts sessions and authentication walkthrough',[
('Factory and startup','create_app reads configuration, requires a SECRET_KEY, initializes SQLAlchemy and CSRF, registers the blueprint and installs response/error handlers. run.py creates a persistent private local key only if none is supplied, invokes init-db and starts Flask without debug reload. init-db creates missing tables and eight shared default categories without deleting accounts. It does not convert arbitrary existing schemas.'),
('Registration','register trims the name, normalizes the email to lowercase and validates lengths and email shape. Passwords need at least eight characters and at most 72 UTF-8 bytes because of bcrypt\'s input limit. bcrypt.gensalt supplies a unique salt. The account stores only password_hash. A unique database email constraint catches duplicates even if requests race, and the exception branch rolls back before returning a field error. Browser success redirects to login; JSON returns 201 with public user fields.'),
('Login and locking','login reads the user and guard, compares any lock expiry with current UTC and returns 429 while locked. It verifies the supplied password with bcrypt before unnecessarily holding a SQLite write lock. Unknown or wrong credentials return 401. A persistent LoginGuard increments failures and locks after the fifth failure for five minutes. A successful login resets the guard, replaces the current login token if needed and stores a new LoginSession with an eight-hour expiry.'),
('Protected requests and logout','load_user reads sid and retrieves its session row, checks expiry and loads g.user. @protected denies an anonymous request before business logic. Browser requests redirect; API calls return 401. logout deletes the server session and expires the cookie. A copied old cookie cannot restore the deleted row. Explain why a random cookie alone would be insufficient without a server-side validity check.'),
('Tests to demonstrate','Use test_logout_revokes_replayed_cookie, registration duplicate/length cases, lockout persistence/expiry cases and the 20-user concurrency check. Explain why the failure counter survives an app restart and why stale sessions must be rejected. A limitation to acknowledge: this is account-based lockout and can be abused to temporarily deny access to a known account.')]),
5:('Budgets dashboard and exact boundary behavior',[
('Budget persistence','budget_list accepts a YYYY-MM month, a positive two-decimal limit and an optional visible category. NULL category denotes the overall limit. The query scopes to g.user.id and the chosen month/category. Existing scope updates; a new scope inserts. A unique expression index prevents duplicate NULL overall scopes. Foreign categories are unavailable even if their numeric ID is guessed. Validation errors must not save a partial budget.'),
('Compute rather than duplicate','dashboard_data parses the month and sums only owned transactions. Income and expense use separate filters. expense_sum includes the selected date bounds and optionally category_id. The application derives balance, remaining and percentage instead of persisting totals that might become stale after edits or deletion. This is simpler for the measured local workload; a future cached aggregate would need invalidation and reconciliation.'),
('Thresholds and examples','Monthly limit 5000 with expense 1800 yields 36 percent and no warning. Change the limit to 2250 and usage is exactly 80 percent, producing warning. Limit 1800 produces exactly 100 percent, still warning. Limit 1799 produces over-budget. The alert is advisory; transaction creation does not reject a new expense merely because a limit was exceeded. Negative remaining amounts are useful and should not be silently clipped to zero.'),
('Charts and dates','Category totals are grouped and ordered for the selected month. Six trend buckets include that month plus five predecessors, including zero months and year rollover. Dates before June 0001 cannot represent the requested six-month trend and return 422. The local charts.js draws Canvas charts while numerical tables retain the values. The app uses server IST to reject future transaction dates; login expiry uses UTC.'),
('Defend the design','A layered monolith keeps deployment and debugging simple for three students. SQLite is adequate for the demonstrated test load but has a single writer. Owner/date indexes speed relevant queries without replacing owner checks. Read-time aggregates avoid stale balances. Describe the difference between an architectural choice, a measured result and an acceptance item that still needs a public host or human participant.')]),
12:('Sathik viva questions and final rehearsal',[
('Why server-side sessions','The cookie stores a random token; the server checks its row and expiry. Logout revokes the row, so cookie replay fails. HttpOnly protects against JavaScript reading the cookie, but it does not eliminate all XSS or CSRF risks.'),
('Why a separate LoginGuard','It adds persistent lockout without replacing existing account rows. Five failures produce a five-minute lock. init-db creates the new table, while full future schema changes still need migrations.'),
('Why did concurrency need a fix','Costly password checking while holding a database write lock can block other SQLite users. Verification was moved before unnecessary write-lock acquisition, then the 20-user case checked all saved records and isolation.'),
('Why not store balance in User','Balance is derived from owned income minus expense for the selected month. Recomputing avoids a second truth that could become stale after edits or deletion. Performance is measured rather than assumed.'),
('What happens at exactly 100 percent','Warning continues at 100 percent. The distinct over alert starts strictly above 100 percent. Further entries remain allowed.'),
('What protects the overall budget from duplicates','The unique index uses owner, month and coalesce(category_id,0), so a NULL overall scope has a stable unique key. Request validation and the commit exception path remain necessary.'),
('What are the current limits','No application-level database encryption, no completed public HTTPS acceptance and no five-first-time-user result. Local response measurements are not public-network load results. Explain these without hiding them.'),
('Two minute rehearsal','Introduce the problem, register/login, show a saved budget and baseline dashboard, point to one owner-scoped query and one assertion, then show the actual CI result. Finish by identifying your genuine PR and one integration dependency on Sahana\'s transactions and Arya\'s export/testing work.'),
('Final self check','Can you explain every function you will open, reproduce a boundary failure, calculate totals without a screen and identify which reports were regenerated for the submitted revision? Read pages 2, 3 and 6 again if any answer is uncertain.')])},
'Sahana':{
1:('Your learning path and project responsibility',[
('What you should be able to explain','Your primary responsibility is the complete transaction lifecycle: expense and income creation, field validation, persisted editing, deletion confirmation and filtered/sorted lists. Your GitHub account is SahanaShivakumarBadiger. The genuine original transaction PR is number 4. Use its actual diff and commit history to explain your contribution; current assignment and AI-assisted recovery work do not rewrite that history.'),
('Start from a user task','A student records Lunch as an INR 250 Food expense paid by UPI. The app validates it, stores it under the signed-in account and includes it in the monthly dashboard and CSV. The payment mode is a label, not a bank transfer. Editing the record must update every derived view; cancelling deletion must preserve it. This end-to-end behavior is your functional feature.'),
('Study order','Run one valid expense and one income through the browser. Read Transaction in models.py, then protected, visible_category, owned_transaction, money, validate_transaction, transaction_rows and the create/edit/delete/detail routes. Follow each template and its form action. Read test_transactions.py, the eight-per-requirement scenarios and the new malformed-ID regression cases. Use pages 4 and 5 for deeper walkthroughs.'),
('Understand the integration','The dashboard does not receive a separate transaction total to save. It queries the same records. CSV reuses the same list query without pagination. Categories are shared defaults or private user records. Authentication supplies g.user; your route must never accept another owner from the form. Explain how these dependencies make the feature coherent.'),
('Completion exercise','Demonstrate a rejected future date, a correctly saved two-decimal amount, an edit that changes dashboard totals, a cancelled delete and a filtered list. Open the exact route and assertion for each. Then explain one budget calculation and one CSV risk outside your primary area. The viva can question the whole codebase, so read the shared pages as well.')]),
4:('Transaction creation and validation walkthrough',[
('The persisted record','Transaction stores id, user_id, expense/income type, Numeric amount, txn_date, optional category_id, payment_mode, source and note. Database checks require positive amount and valid type. Expenses require category and payment mode; income requires source. Indexes on owner/date and owner/category support list and aggregate queries. The application performs stronger input and ownership validation before reaching the database.'),
('Creation flow','POST /transactions passes CSRF and authentication, then payload reads a form or JSON object. validate_transaction normalizes the type, calls money, parses the date and rejects a future date using server IST. For an expense it resolves a visible category and validates payment mode. For income it requires source. Notes are optional and limited to 2000 characters. Invalid input returns 422 with correction details and does not commit.'),
('Use precise boundary reasoning','Zero, negative, blank, text, NaN and Infinity amounts are invalid. More than two decimals is invalid; INR 0.01 is valid. The maximum accepted amount is 9999999999.99. A malformed category such as true, 1.9 or a huge integer must return unavailable rather than silently coercing to category 1 or crashing SQLite. This recovery added regression tests for those cases. Missing category selection is a field error; a foreign category is 404.'),
('Persist and respond','Valid values create Transaction(user_id=g.user.id,...). The server commits once. JSON success is 201 with the saved transaction. HTML success redirects to the list. The response does not include recalculated budgets; a later dashboard read computes them. If an unexpected write fails, the application rolls back and returns a safe retry message rather than showing a stack trace.'),
('Exercise','Trace a valid expense and an invalid one side by side in the code. Point to the line that establishes ownership and the branch that prevents a save. Then explain why browser min and max attributes improve usability but cannot replace server validation: a caller can submit a request without using that form.')]),
5:('Editing deletion filtering and pagination',[
('Owner lookup first','owned_transaction selects a row by both id and g.user.id. A foreign or missing row returns 404 before mutation. The edit route begins with that lookup, validates changes with the existing transaction as defaults, assigns only validated fields and commits. Switching type clears irrelevant expense/income fields. Invalid edits must leave the original record and dashboard values unchanged.'),
('Deletion is a workflow','A GET confirmation page must never delete data. An HTML POST needs confirm=yes; Cancel keeps the record. An authenticated CSRF-protected JSON DELETE is an explicit API action. After deletion, detail returns 404 and dashboard aggregates change. The route scopes ownership first so a guessed ID cannot remove someone else\'s record. Explain why simply hiding the Delete button would not provide authorization.'),
('One query for listing and reporting','transaction_rows begins with the owner predicate. It parses inclusive start/end dates, visible category and amount bounds, chooses a whitelisted sort column and applies stable ID ordering for ties. Invalid ranges return field errors. Recovery bounds extreme filter amounts before they reach SQLite. The list is capped at 50 rows, with one extra row queried to determine has_next. Filtered total sums all matching rows, not merely the displayed page.'),
('Pagination and export differ deliberately','The screen uses a positive page number and offset. Export reuses filters and ordering with limit=None, so it includes every matching row across all pages. Explain this when a CSV contains more rows than the first screen. It is the same filtered dataset, viewed in two different ways. The chart and budget queries read the persisted records independently, so edit/delete effects appear on the next read.'),
('Tests to show','Choose cases for a smallest valid amount, future date, invalid edit rollback, cancelled deletion, foreign-user mutation, ascending/descending filters and export beyond 50 rows. Describe initial data and expected totals before running them. A good demonstration validates stored values and derived views rather than relying only on a success flash message.')]),
12:('Sahana viva questions and final rehearsal',[
('Why server validation if the input is a number field','HTML validation is convenience. Direct HTTP or JSON callers can bypass it. money rejects invalid and non-finite values and ensures positive two-decimal limits on the server.'),
('How is another user\'s record protected','The session supplies g.user, and owned_transaction queries both record ID and owner ID. Foreign and absent records return 404. Hiding buttons is not authorization.'),
('Why does an expense require a category','The SRS groups expenses for budgets and charts. Only shared defaults and the current user\'s custom categories are visible. Income uses source instead and does not consume a category budget.'),
('How does an edit update balance','The app changes the transaction and commits. The dashboard recomputes sums from stored records on its next GET, so it does not maintain a separate stale balance field.'),
('What is the deletion contract','GET shows a confirmation. Form deletion requires confirm=yes. Cancel preserves the row. JSON DELETE is an explicit authenticated and CSRF-protected action. Ownership is checked before all paths.'),
('Why is the CSV larger than the page','Pages show up to 50 records. Export uses the identical owner/filter/sort query without pagination, so it includes all matches. The filtered total also covers the complete matching dataset.'),
('What was wrong with numeric category coercion','int(true) becomes 1 and int(1.9) truncates to 1 in Python. The repaired route accepts only a valid positive integer representation within SQLite range. Malformed or unavailable categories safely return 404.'),
('Two minute rehearsal','Start with baseline totals, create an expense, reject an invalid amount, edit a saved row, cancel a delete and show a sorted filter. Open the source validation function and one corresponding assertion. Show original PR 4 from your account and explain one review finding without claiming work you did not perform.'),
('Final self check','Can you demonstrate a failed save without a partial record, explain the 80 percent budget boundary and describe formula-safe CSV? Read the shared security and testing pages again if any cross-feature explanation is uncertain.')])},
'Arya':{
1:('Your learning path and project responsibility',[
('What you should be able to explain','Your current full functional responsibility is filtered CSV reporting, with quality and security verification across the application. Your account is arya7sai, and the genuine original test PR is number 3. The original work includes test development; current reporting ownership does not retroactively make you author of earlier export implementation or November AI-assisted repairs. Review the actual export code and make any future contribution through your own PR.'),
('Start from the user need','A user filters their records for a month and exports all matching transactions to a spreadsheet. Correct reporting must preserve ownership, filters, ordering, money, Unicode and CSV escaping. It must include matches beyond the first 50-row screen. A useful statement is: I verify that the exported report is a complete, safe representation of the signed-in user\'s filtered records.'),
('Study order','Read transaction_rows, transaction_export, safe_cell and transaction_record. Follow the filtered export link in transactions.html. Read test_csv_export.py and the eight reporting scenarios. Next inspect test_nonfunctional.py, test_security.py and scripts/quality.py. Read JUnit XML, coverage.json and the four named reports. Pages 4 and 5 explain how to defend the feature and evidence.'),
('Understand the whole flow','Authentication supplies the owner; Sahana\'s transaction feature supplies validated records; Sathik\'s dashboard computes totals from those same rows. Your report query must not invent a separate filter implementation with different behavior. Security and test evidence are cross-cutting responsibilities, so be ready to explain hashing, CSRF, rollback, lockout and the difference between statement and branch coverage.'),
('Completion exercise','Export a known filtered dataset with a comma, quote, newline and formula-like note. Verify every value and row count, including more than 50 rows. Explain the two deployed-test skips and identify a branch coverage miss. Finally open original PR 3 and describe which tests you authored and what defects they exposed.')]),
4:('Filtered reporting and CSV code walkthrough',[
('Reuse the owner-scoped query','transaction_export calls transaction_rows with limit=None. That function starts with Transaction.user_id == g.user.id, applies the same inclusive date/category/amount filters and whitelisted ordering as the list, and skips pagination for the export. This prevents separate screen/report logic from drifting. Validation errors must stop the export rather than silently output a broader dataset.'),
('Define the output contract','The response is UTF-8 text/csv with attachment filename smartexpense.csv. Header columns are date,type,category,amount,payment_mode,source,note. Money is formatted to two decimals and dates use ISO format. Category IDs are translated to visible names. csv.writer handles commas, quotes and embedded line breaks correctly; splitting lines or joining strings manually would corrupt some valid fields.'),
('Spreadsheet formula risk','A text field beginning with =, +, - or @ may be interpreted as a formula by spreadsheet software. safe_cell examines dangerous prefixes, including leading whitespace situations and initial tab/newline/carriage-return cases, and prefixes an apostrophe. Tests should check the parsed cell value and confirm that malicious text is neutralized. CSV syntax escaping alone does not address formula interpretation.'),
('Complete means across pages','A screen can show 50 rows while the filtered dataset has 59 or more. Export must include all matches, use the requested sorting and exclude foreign-user records. An empty export still contains the header. Verify special characters and Unicode with csv.reader, because raw newline counts are wrong when a quoted field contains a line break.'),
('Limitations and extension','The current export constructs the CSV in memory. That is acceptable for the measured mini-project size but is not unlimited-scale streaming. A large-data extension would use a bounded iterator and a stable snapshot, preserving owner checks, escaping and failure behavior. Do not claim streaming merely because an old specification used that word. Show the implementation and explain the tradeoff.')]),
5:('Quality reporting and security verification',[
('Follow the report generator','scripts/quality.py runs isolated unit tests, then the complete suite under coverage.py branch measurement. It writes JUnit XML, markdown case results, captured logs and coverage JSON/XML/HTML. It separately reports statement and branch percentages, runs pyflakes and Bandit, and records the base revision, time, Python version and whether working-tree changes were included. CI regenerates evidence for its exact revision.'),
('Interpret rather than decorate','A green count is not proof of all requirements. A skip means unavailable execution, not pass. Coverage measures whether code ran, not whether assertions are meaningful. Statement and branch denominators differ. Combined coverage should not be quoted as pure statement or branch coverage. The HTML and JSON show misses; explain which input could exercise one instead of promising 100 percent without evidence.'),
('Nonfunctional tests','Performance inserts 5000 transactions and measures 100 dashboard and 100 list requests, requiring at least 90 below three seconds. It also checks correct totals and 50 visible records. Concurrency uses 20 independent clients, 260 successful actions and owner-isolated persisted results. Reliability restarts an application on the same SQLite file and forces a failure after flush but before commit. These are controlled local checks, not a public network benchmark.'),
('Security evidence','Password tests inspect salted hashes and boundaries. Ownership tests use two accounts and malicious record IDs. SQL/XSS cases exercise inert handling, and CSRF tests reject missing tokens. Persistent lockout tests check restart, expiry and reset. New regressions reject category booleans/fractions/overflow and oversized filter amounts. Static tools complement these cases; no clean scan can prove absence of every vulnerability.'),
('Manual boundaries','Five first-time users must actually attempt the entry/error task. The stable Chrome/Edge/Firefox matrix passed 90 desktop/360px checkpoints and closes issue 26. Public TLS still needs a real HTTPS host, valid certificate and redirect. Keep issues 25 and 27 open until the required evidence exists. During the viva, distinguish implementation complete, locally verified and fully accepted.')]),
12:('Arya viva questions and final rehearsal',[
('Why share the list query with export','It keeps ownership, filters and ordering consistent. Export disables pagination to return all matches rather than copying only the visible page.'),
('Why not count CSV lines','A quoted note may contain a newline. Parse using csv.reader and count records; verify headers and field values independently.'),
('What is CSV injection','A spreadsheet may evaluate formula-like text. Prefix dangerous text with an apostrophe. csv.writer handles delimiter escaping, which is a separate problem.'),
('What is branch coverage','It measures executed branch exits divided by possible exits. Statement coverage measures executable lines. The combined coverage metric includes both opportunities and must not be labelled as either individual metric.'),
('What do the skipped tests establish','They establish that public HTTPS checks were not run without a configured URL. They are not passes and do not close SEB-SR-001.'),
('How do you know a fast page is correct','Performance assertions also check expected totals, row caps and owner isolation. A quickly returned error or incomplete dataset should fail the test.'),
('Why force failure after flush','It ensures a database write occurred inside the transaction before failure. A correct rollback removes that uncommitted change, and a retry should succeed without a half-save.'),
('Two minute rehearsal','Show a filtered list, export a known dataset and parse its records, demonstrate a formula-like note safely, then open the report generator and distinguish the three coverage measures. Show your actual PR 3 and explain the defects its tests exposed. Identify a reporting improvement you can genuinely submit from your own account.'),
('Final self check','Can you trace a CSV row back to an owned Transaction, explain lockout and bcrypt, calculate budget usage and name each evidence artifact? Use the shared architecture and security pages to close any gap before presenting.')])}}


def build_guides():
    from guide_repository_pages import page as repository_page, code_block
    evidence=json.loads((DOCS/'repository-evidence.json').read_text())
    context={'p':p,'table':table,'S':S,'DOCS':DOCS,'evidence':evidence}
    for person,role in ROLE_GUIDE.items():
        story=[]
        for number in range(1,13):
            if number>1:story.append(PageBreak())
            special=repository_page(person,number,context)
            if special is not None:
                story.extend(special)
                continue
            heading,items=role.get(number,COMMON_GUIDE.get(number))
            story.append(p(f'{number:02} {heading}','GuideTitle'))
            for name,text in items:
                story.append(p(name,'GuideH'));story.append(p(text,'CodeText' if name=='Useful commands' else 'Body'))
            if number in (4,5):story.extend(code_block(person,number,context))
            if number==7:
                story.append(p('Your exact executable checks','GuideH'))
                details={'Sathik':'tests/test_core.py: test_logout_revokes_replayed_cookie, test_budget_persistence_upsert_and_totals, test_alert_thresholds and test_year_rollover_trend. Run python -m pytest tests/test_core.py -q.',
                  'Sahana':'tests/test_transactions.py checks CRUD and filters; tests/test_regressions.py checks malformed category IDs and extreme amount filters. Run python -m pytest tests/test_transactions.py tests/test_regressions.py -q.',
                  'Arya':'tests/test_csv_export.py; test_nonfunctional.py; test_security.py. Reusable account/write/CSRF fixtures are in tests/support.py. Run python -m pytest tests/test_csv_export.py tests/test_nonfunctional.py tests/test_security.py -q.'}
                story.append(p(details[person]))
            if number==9 and (DOCS/'milestones.json').exists():
                story.append(p('Actual milestone snapshot','GuideH'))
                ms=json.loads((DOCS/'milestones.json').read_text())
                story.append(table(['Milestone','Closed and open','Planned due','State'],[[m['title'],f"{m['closed_issues']} closed / {m['open_issues']} open",m['due_on'][:10],m['state']] for m in ms],[135,145,110,113]))
            if number==11:
                story.append(p('Where the remaining checks are recorded','GuideH'))
                story.append(p('docs/acceptance-remaining.md explains issues 25-27; docs/usability-participants.csv has five unobserved participant rows to complete honestly. Browser results live in docs/reports/browser-acceptance. Deployed checks are tests/test_security.py tests with deployed in their names. Do not close a requirement without its actual evidence.'))
        pdf(f'viva/{person}_Viva_Guide.pdf',story)


def build_report():
    st=title('SmartExpense Software Engineering Project Report','Team 14 synopsis implementation validation and maintenance')
    st+=section('1 Project proposal and synopsis','Project: Smart Expense and Budget Management. Course UE24CS341A, Section 5G, Team 14. Sathik (PES2UG24CS430), Arya (PES2UG24CS429) and Sahana (PES2UG24CS427) form the current team. The application addresses a student\'s need to record spending, compare it with income and recognize budget pressure. No customer interview is claimed. Representative users are students or individuals comfortable with ordinary web forms.',
      'Functional features: register and authenticate; manage private expenses and income; add/rename private categories; set monthly and category budgets; show exact totals, threshold alerts and six-month charts; filter/sort transactions and export CSV. Scope excludes bank connections, real payment execution, shared budgets, multi-currency, tax and statement import.')
    st+=section('2 Requirements and traceability','SRS.pdf defines 17 functional, five nonfunctional and five security requirements, with two explicit security objectives. Requirements.json and traceability.csv connect IDs to ownership, estimates, sprints, source, tests and GitHub issues. Test_Plan.pdf contains the verification strategy and catalog; SAD.pdf describes the actual implementation. These are the updated authoritative specifications; historical versions remain in Git history.')
    st+=section('3 Planning and product ownership','The project uses Agile increments with a working foundation and later integrated transactions/reporting. The separate Team14_Project_Plan.pdf includes tools, build/reuse decisions, WBS, rough person-month estimates and schedule. Sathik is responsible for accounts, budgets and dashboard; Sahana for transaction lifecycle; Arya for reporting/export and quality/security verification. All three should understand and review the integrated code.',
      'The GitHub backlog has 27 mapped items with assignees, point estimates and sprint milestones. Current responsibility is recorded in November rather than presented as historical proof. Original member PRs and commit identities remain available; repairs are real AI-assisted work under the account that performed them. Projects board completion depends on project-scoped access and is tracked separately from the issue backlog.')
    st+=section('4 Architecture and implementation','A layered monolith combines Jinja/Canvas browser UI, Flask request handling and SQLAlchemy/SQLite persistence. Authentication uses salted bcrypt, opaque revocable sessions and persistent login lockout. Validation establishes positive exact two-decimal money, valid dates and category ownership. Owner predicates protect lists, mutations, totals and exports. Budgets and dashboard values are computed from stored transactions, avoiding duplicate total state.')
    st.append(DIAGRAMS['components']);st+=section('5 Design diagrams and interfaces','The SAD contains use-case and component views plus login and expense UML sequences. All four diagrams also have editable SVG assets in diagrams. api-contract.md records form and JSON behavior. Expense creation returns its saved record; dashboard GET returns derived totals. Original alternative response examples and four-member rosters were superseded in the current files. deviations.md records implementation and delivery differences.')
    st+=section('6 Testing and results','The executable suite includes isolated unit rules, 136 functional scenarios, security/CSV/transaction regressions, 5000-row performance, 20-user concurrency and restart/rollback checks. Unit, system, statement and branch reports are under reports. JUnit and coverage files preserve machine-readable detail. Browser recordings use synthetic data and real form submissions; videos are retrospective current-build evidence.')
    if METRICS:
        m=METRICS;t=m['coverage'];st.append(table(['Measure','Actual result'],[
         ['Unit tests',f"{m['unit']['passed']} passed"],['Complete regression suite',f"{m['suite']['passed']} passed; {m['suite']['failed']} failed; {m['suite']['skipped']} skipped"],
         ['Statement coverage',f"{100*t['covered_lines']/t['num_statements']:.2f}%"],['Branch coverage',f"{100*t['covered_branches']/t['num_branches']:.2f}%"],['Combined coverage',f"{t['percent_covered']:.2f}%"]],[200,303]))
    st+=section('7 Security validation and limitations','Automated evidence checks salts, password bounds, persistent lockout, replay rejection, owner authorization, CSRF, injection/XSS handling, CSV formulas, headers and safe rollback errors. pyflakes and Bandit complement executable tests. No full penetration-test certification is claimed. SQLite is not encrypted by this app. The 90-check stable-browser matrix is verified. Public HTTPS and five-real-user acceptance remain explicit open checks.')
    st+=section('8 Maintenance and recovery','maintenance.md specifies safe SQLite backups, restore validation, dependency updates, code rollback, logging hygiene and severity-based defect handling. init-db is nondestructive table creation, not a general column migration system. CI builds a non-root container with Gunicorn and persistent storage requirements. Actual public hosting still needs a host, domain, certificate and secure proxy configuration.')
    st+=section('9 Final demonstration and outcome','A fifteen-minute presentation should cover the problem and SRS, architecture/data/sequences, working use cases, backlog/PR/review evidence, tests/coverage, deviations and maintenance. The one-minute and two-minute retrospective videos in videos demonstrate the repaired working product. Final acceptance is conditional until evaluation-checklist.md has the required external evidence and genuine review/sign-off. A release candidate must not be misrepresented as complete human acceptance.')
    st+=section('10 LLM use and references','LLMs are permitted by the supplied project guidelines. The repair uses AI to inspect documents, fix boundary behavior, develop tests, reconcile requirements and prepare guides. The team must understand the submitted code and verify the generated work. ai-use.md records the request and method without inventing earlier prompts. References: teacher guidelines, deliverables Parts 1-3, student FAQs and evaluator checklist in source-reference; current source, tests and reports in this repository.')
    screenshot=DOCS/'reports/browser/sprint1-totals.png'
    if screenshot.exists():
        st+=section('11 Working product screenshot','Synthetic account showing persisted income, expense, balance and budget usage. The underlying browser checks and recordings are in reports/browser and videos.')
        st.append(FlowImage(str(screenshot),width=500,height=351))
    pdf('Project_Report.pdf',st)


def main():
    import sys
    if '--guides-only' in sys.argv:
        build_guides()
        print('Updated the three repository-specific viva guides.')
        return
    for name,drawing in DIAGRAMS.items():renderSVG.drawToFile(drawing,str(DOCS/'diagrams'/(name+'.svg')))
    build_srs();build_sad();build_test_plan();build_plan();build_report();build_guides()
    print('Built five submission PDFs and three personalized viva guides.')

if __name__=='__main__':main()
